package org.mockito.internal.invocation;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Array;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.internal.invocation.Invocation;
import org.mockito.internal.invocation.InvocationMatcher;
import org.mockito.internal.matcher.Matcher;
import org.mockito.internal.matchers.CapturesArguments;
import org.mockito.internal.matchers.MatcherDecorator;
import org.mockito.internal.reporting.PrintSettings;
import org.mockito.invocation.DescribedInvocation;
import org.mockito.invocation.Invocation;
import org.mockito.invocation.Location;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class InvocationMatcher_captureArgumentsFrom_TriageGen2Test {

    private List<Matcher> matchers;
    private Invocation invocation;
    private Method normalMethod;
    private Method varArgsMethod;

    // Mock implementation of CapturesArguments to verify calls
    public interface CapturesArguments extends Matcher {
        void captureFrom(Object argument);
    }

    @Before
    public void setUp() throws NoSuchMethodException {
        matchers = new ArrayList<>();
        invocation = mock(Invocation.class);

        normalMethod = this.getClass().getMethod("dummyMethod", String.class, Integer.class);
        varArgsMethod = this.getClass().getMethod("varArgsMethod", String.class, String[].class);
    }

    public void dummyMethod(String s, Integer i) {}
    public void varArgsMethod(String s, String... args) {}

    @Test
    public void testCaptureArgumentsFrom_NonVarargs_WithCaptures() {
        when(invocation.getMethod()).thenReturn(normalMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{"hello", 123});

        CapturesArguments m1 = mock(CapturesArguments.class);
        CapturesArguments m2 = mock(CapturesArguments.class);
        matchers.add(m1);
        matchers.add(m2);
        matchers.add(mock(Matcher.class)); // Should be ignored (not instance of CapturesArguments)

        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);
        matcher.captureArgumentsFrom(invocation);

        verify(m1).captureFrom("hello");
        verify(m2).captureFrom(123);
    }

    @Test
    public void testCaptureArgumentsFrom_NonVarargs_NoCaptures() {
        when(invocation.getMethod()).thenReturn(normalMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{"hello", 123});

        matchers.add(mock(Matcher.class));
        matchers.add(mock(Matcher.class));

        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);
        matcher.captureArgumentsFrom(invocation);
        // No exceptions means success
    }

    @Test
    public void testCaptureArgumentsFrom_Varargs_StandardArguments() {
        when(invocation.getMethod()).thenReturn(varArgsMethod);
        // Raw arguments: [fixed_arg, vararg_array]
        // The code calculates indexOfVararg = length - 1
        Object[] rawArgs = new Object[]{"fixed", new String[]{"a", "b"}};
        when(invocation.getRawArguments()).thenReturn(rawArgs);

        // Mock getArgumentAt for the non-vararg part
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("fixed");

        CapturesArguments m1 = mock(CapturesArguments.class); // For "fixed"
        CapturesArguments m2 = mock(CapturesArguments.class); // For vararg index 0 ("a")
        CapturesArguments m3 = mock(CapturesArguments.class); // For vararg index 1 ("b")

        matchers.add(m1);
        matchers.add(m2);
        matchers.add(m3);

        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);
        matcher.captureArgumentsFrom(invocation);

        verify(m1).captureFrom("fixed");
        // In the vararg loop: position starts at indexOfVararg (1)
        // m2 is at position 1. m2.captureFrom(rawArgs[1 - 1]) -> rawArgs[0] is incorrect logic in source?
        // Looking at source: position - indexOfVararg. If position=1, indexOfVararg=1, index=0.
        // Wait, rawArgs[0] is "fixed". The source logic for varargs seems to treat the array as flattened or uses index relative to vararg start.
        // Let's verify based on the provided source logic:
        verify(m2).captureFrom(rawArgs[0]); 
        verify(m3).captureFrom(rawArgs[1]);
    }

    @Test
    public void testCaptureArgumentsFrom_Varargs_OnlyVarargs() {
        when(invocation.getMethod()).thenReturn(varArgsMethod);
        Object[] rawArgs = new Object[]{"onlyVarargArray"};
        when(invocation.getRawArguments()).thenReturn(rawArgs);

        CapturesArguments m1 = mock(CapturesArguments.class);
        matchers.add(m1);

        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);
        matcher.captureArgumentsFrom(invocation);

        // indexOfVararg = 1 - 1 = 0.
        // Loop 1: 0 to 0 (no iterations)
        // Loop 2: 0 to 1. position 0: m1.captureFrom(rawArgs[0-0])
        verify(m1).captureFrom("onlyVarargArray");
    }

    @Test
    public void testCaptureArgumentsFrom_EmptyMatchers() {
        when(invocation.getMethod()).thenReturn(normalMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{});

        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);
        matcher.captureArgumentsFrom(invocation);
        // Should do nothing
    }

    @Test
    public void testCaptureArgumentsFrom_Varargs_WithMixedMatchers() {
        when(invocation.getMethod()).thenReturn(varArgsMethod);
        Object[] rawArgs = new Object[]{"arg0", new String[]{"arg1", "arg2"}};
        when(invocation.getRawArguments()).thenReturn(rawArgs);
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("arg0");

        CapturesArguments m1 = mock(CapturesArguments.class);
        Matcher m2 = mock(Matcher.class); // Not a CapturesArguments
        CapturesArguments m3 = mock(CapturesArguments.class);

        matchers.add(m1);
        matchers.add(m2);
        matchers.add(m3);

        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);
        matcher.captureArgumentsFrom(invocation);

        verify(m1).captureFrom("arg0");
        verify(m3).captureFrom(rawArgs[1]); // position 2, indexOfVararg 1 -> index 1
    }
}
